async function WAKING_UP() {
  let x = 0, n_ = 0;
  g.DAY = g.DAY + 1;
  g.SICKNESS_WARNING_FLAG = true;
  g.SLEEPY_LEVEL = 0;
  await RESET_TIME();
  x = first(ADVENTURER);
  loop1: for (;;) {
    if (x) {
      n_ = next(x);
      if (!(hasFlag(x, WORNBIT))) {
        move(x, g.HERE);
      }
      if ((x == CANTEEN) && (loc(HIGH_PROTEIN) == CANTEEN) && hasFlag(CANTEEN, OPENBIT)) {
        remove(HIGH_PROTEIN);
      }
      if ((x == FLASK) && (loc(CHEMICAL_FLUID) == FLASK)) {
        remove(CHEMICAL_FLUID);
      }
      x = n_;
    } else {
      break loop1;
    }
  }
  tell("\n***** SEPTEM ", N(g.DAY + 5), ", 11344 *****\n\n");
  if (!(loc(ADVENTURER) == BED)) {
    tell("You wake and slowly stand up, feeling stiff from your night on the floor.");
  } else if (g.SICKNESS_LEVEL < 3) {
    tell("You wake up feeling refreshed and ready to face the challenges of this mysterious world.");
  } else if (g.SICKNESS_LEVEL < 6) {
    tell("You wake after sleeping restlessly. You feel weak and listless.");
  } else {
    tell("You wake feeling weak and worn-out. It will be an effort just to stand up.");
  }
  if (g.HUNGER_LEVEL > 0) {
    g.HUNGER_LEVEL = 4;
    enable(await QUEUE(I_HUNGER_WARNINGS.id, 100));
    tell(" You are also incredibly famished. Better get some breakfast!");
  } else {
    enable(await QUEUE(I_HUNGER_WARNINGS.id, 400));
  }
  crlf();
  if (hasFlag(FLOYD, RLANDBIT) && g.FLOYD_INTRODUCED) {
    move(FLOYD, g.HERE);
    g.FLOYD_SPOKE = true;
    if (loc(ADVENTURER) == BED) {
      tell("Floyd bounces impatiently at the foot of the bed. \"About time you woke up, you lazy bones! Let's explore around some more!\"\n");
      return true;
    } else {
      tell("Floyd gives you a nudge with his foot and giggles. \"You sure look silly sleeping on the floor,\" he says.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function RESET_TIME() {
  if (g.DAY == 2) {
    clearFlag(BALCONY, TOUCHBIT);
    g.INTERNAL_MOVES = 1600 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 5800));
  } else if (g.DAY == 3) {
    clearFlag(BALCONY, TOUCHBIT);
    g.INTERNAL_MOVES = 1750 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 5550));
  } else if (g.DAY == 4) {
    clearFlag(WINDING_STAIR, TOUCHBIT);
    g.INTERNAL_MOVES = 1950 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 5200));
  } else if (g.DAY == 5) {
    clearFlag(WINDING_STAIR, TOUCHBIT);
    g.INTERNAL_MOVES = 2150 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 4800));
  } else if (g.DAY == 6) {
    clearFlag(COURTYARD, TOUCHBIT);
    g.INTERNAL_MOVES = 2450 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 4300));
  } else if (g.DAY == 7) {
    clearFlag(COURTYARD, TOUCHBIT);
    g.INTERNAL_MOVES = 2800 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 3700));
  } else if (g.DAY == 8) {
    g.INTERNAL_MOVES = 3200 + random(80);
    return enable(await QUEUE(I_SLEEP_WARNINGS.id, 3000));
  } else if (g.DAY == 9) {
    return (await JIGS_UP("Unfortunately, you don't seem to have survived the night."));
  } else {
    return false;
  }
}

