async function DESCRIBE_ROOM(look$ = false) {
  let v$ = 0, str = 0, av = 0;
  v$ = look$ || g.VERBOSE;
  if (!g.LIT) {
    tell("It is pitch black. You might be eaten by a grue.\n");
    if (g.HERE == TRANSPORTATION_SUPPLY) {
      tell("There is light to the south.\n");
    }
    return false;
  }
  if (!(hasFlag(g.HERE, TOUCHBIT))) {
    setFlag(g.HERE, TOUCHBIT);
    v$ = true;
  }
  if (loc(g.HERE) == ROOMS) {
    tell(D(g.HERE));
    if (hasFlag(loc(ADVENTURER), VEHBIT)) {
      tell(", in the ", D(loc(ADVENTURER)));
    }
    crlf();
  }
  if (look$ || !g.SUPER_BRIEF) {
    av = loc(ADVENTURER);
    if (v$ && (await apply(getProp(g.HERE, P.ACTION), M_LOOK))) {
      return true;
    } else if (v$ && (str = getProp(g.HERE, P.LDESC))) {
      tell(S(str), "\n");
    } else {
      await apply(getProp(g.HERE, P.ACTION), M_FLASH);
    }
    if (!(g.HERE == av) && hasFlag(av, VEHBIT)) {
      await apply(getProp(av, P.ACTION), M_LOOK);
    }
  }
  return true;
}

