async function FINISH(died, repeating = false) {
  crlf();
  if (!repeating) {
    await V_SCORE();
    if (died) {
      tell("\nOh, well. According to the Treaty of Gishen IV, signed in 8747 GY, all adventure game players must be given another chance after dying. In the interests of interstellar peace...\n");
    }
  }
  putb(g.P_INBUF, 0, 10);
  tell("\nWould you like to restart the game from the beginning, restore a saved game position, or end this session of the game? (Type RESTART, RESTORE, or QUIT.)\n\n>");
  await read(g.P_INBUF, g.P_LEXV);
  putb(g.P_INBUF, 0, 80);
  if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
    await restart();
    tell("Failed.\n");
    return await FINISH(false, true);
  } else if (eq(get(g.P_LEXV, 1), W.RESTOR)) {
    if (await restore()) {
      tell("Ok.\n");
      return true;
    } else {
      tell("Failed.\n");
      return await FINISH(false, true);
    }
  } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q)) {
    return await quit();
  } else {
    return await FINISH(false, true);
  }
}

