async function ITAKE(vb = true) {
  let cnt = 0, obj = 0;
  let $1;
  if (!(hasFlag(g.PRSO, TAKEBIT))) {
    if (vb) {
      $1 = await PICK_ONE(g.YUKS);
      tell(S($1));
      tell("\n");
    }
    return false;
  } else if (!(loc(loc(g.PRSO)) == ADVENTURER) && (((await WEIGHT(g.PRSO)) + (await WEIGHT(ADVENTURER))) > g.LOAD_ALLOWED)) {
    if (vb) {
      tell("Your load is too heavy.\n");
    }
    return M_FATAL;
  } else if (((cnt = await CCOUNT(ADVENTURER)) > g.FUMBLE_NUMBER) && prob(cnt * g.FUMBLE_PROB)) {
    obj = first(ADVENTURER);
    loop1: for (;;) {
      if (hasFlag(obj, WORNBIT)) {
        obj = next(obj);
      } else {
        break loop1;
      }
    }
    tell("Oh, no. The ", D(obj), " slips from your arms while taking the ", D(g.PRSO), " and both tumble to the ground.\n");
    if ((FLASK == obj || FLASK == g.PRSO) && (loc(CHEMICAL_FLUID) == FLASK)) {
      remove(CHEMICAL_FLUID);
      tell("Unfortunately, the chemical spills out of the flask and evaporates.\n");
    }
    if ((CANTEEN == obj || CANTEEN == g.PRSO) && (loc(HIGH_PROTEIN) == CANTEEN) && hasFlag(CANTEEN, OPENBIT)) {
      remove(HIGH_PROTEIN);
      tell("To make matters worse, the high-protein liquid spills all over the place and then evaporates.\n");
    }
    move(obj, g.HERE);
    move(g.PRSO, g.HERE);
    return M_FATAL;
  } else {
    move(g.PRSO, ADVENTURER);
    clearFlag(g.PRSO, NDESCBIT);
    await SCORE_OBJ(g.PRSO);
    setFlag(g.PRSO, TOUCHBIT);
    if (g.PRSO == g.SPOUT_PLACED) {
      g.SPOUT_PLACED = GROUND;
    }
    return true;
  }
}

