async function V_OPEN() {
  let f = 0, str = 0;
  if (!(hasFlag(g.PRSO, CONTBIT)) && !(hasFlag(g.PRSO, DOORBIT))) {
    tell("You must be very clever to do that to the ", D(g.PRSO), ".\n");
    return true;
  } else if (hasFlag(g.PRSO, DOORBIT) || !(eq(getProp(g.PRSO, P.CAPACITY), 0))) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      return (await ALREADY("open"));
    } else {
      setFlag(g.PRSO, OPENBIT);
      if (hasFlag(g.PRSO, DOORBIT)) {
        tell("The ", D(g.PRSO), " is now open.\n");
        return true;
      } else if (!(first(g.PRSO)) || hasFlag(g.PRSO, TRANSBIT)) {
        tell("Opened.\n");
        return true;
      } else if ((f = first(g.PRSO)) && !(next(f)) && (str = getProp(f, P.FDESC))) {
        tell("The ", D(g.PRSO), " opens.\n");
        tell(S(str), "\n");
        return true;
      } else {
        tell("Opening the ", D(g.PRSO), " reveals ");
        await PRINT_CONTENTS(g.PRSO);
        tell(".\n");
        return true;
      }
    }
  } else {
    tell("The ", D(g.PRSO), " cannot be opened.\n");
    return true;
  }
}

