async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true, it$ = false, two$ = false;
  if (f = first(obj)) {
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
      } else {
        tell(", ");
        if (!n_) {
          tell("and ");
        }
      }
      tell("a ", D(f));
      if (!it$ && !two$) {
        it$ = f;
      } else {
        two$ = true;
        it$ = false;
      }
      f = n_;
      if (!f) {
        if (it$ && !two$) {
          await THIS_IS_IT(it$);
        }
        return true;
      }
    }
  } else {
    return false;
  }
}

