async function GOTO(rm, v$ = true) {
  let wloc = loc(g.WINNER), olit = 0;
  olit = g.LIT;
  move(ADVENTURER, rm);
  g.HERE = rm;
  g.LIT = await LIT$(g.HERE);
  if (!olit && !g.LIT && prob(75)) {
    (await JIGS_UP("Oh, no! Something (a grue?) slithered into the room and devoured you!"));
    return true;
  }
  if (eq(await apply(getProp(g.HERE, P.ACTION), M_ENTER), 2)) {
    return true;
  }
  if (v$) {
    await V_FIRST_LOOK();
  }
  await SCORE_OBJ(rm);
  return true;
}

