async function V_LOOK_INSIDE() {
  if (hasFlag(g.PRSO, ACTORBIT)) {
    tell("There is nothing special to be seen.\n");
    return true;
  } else if (hasFlag(g.PRSO, DOORBIT)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("The ", D(g.PRSO), " is open, but I can't tell what's beyond it");
    } else {
      tell("The ", D(g.PRSO), " is closed");
    }
    tell(".\n");
    return true;
  } else if (hasFlag(g.PRSO, CONTBIT)) {
    if (!(hasFlag(g.PRSO, OPENBIT))) {
      await PERFORM(V.OPEN, g.PRSO);
      return true;
    } else if (await SEE_INSIDE$(g.PRSO)) {
      if (first(g.PRSO) && (await PRINT_CONT(g.PRSO))) {
        return true;
      } else if (hasFlag(g.PRSO, SURFACEBIT)) {
        tell("There is nothing on the ", D(g.PRSO), ".\n");
        return true;
      } else {
        tell("The ", D(g.PRSO), " is empty.\n");
        return true;
      }
    } else {
      tell("The ", D(g.PRSO), " is closed.\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, TRANSBIT)) {
    tell("You can see dimly through the ", D(g.PRSO), ".\n");
    return true;
  } else {
    tell("You can't look inside ");
    await A_AN();
    tell(D(g.PRSO), ".\n");
    return true;
  }
}

