async function V_SHAKE() {
  let x = 0;
  if (!(await HELD$(g.PRSO)) && !(g.PRSO == HANDS)) {
    return await NOT_HOLDING();
  } else if (g.PRSO == LASER) {
    if (loc(OLD_BATTERY) == LASER) {
      move(OLD_BATTERY, g.HERE);
      return await BATTERY_FALLS();
    } else if (loc(NEW_BATTERY) == LASER) {
      move(NEW_BATTERY, g.HERE);
      return await BATTERY_FALLS();
    } else {
      tell("Shaken.\n");
      return true;
    }
  } else if (!(hasFlag(g.PRSO, OPENBIT)) && first(g.PRSO)) {
    tell("It sounds as if there is something inside the ", D(g.PRSO), ".\n");
    return true;
  } else if (hasFlag(g.PRSO, OPENBIT)) {
    if ((g.PRSO == FOOD_KIT) && ((loc(RED_GOO) == FOOD_KIT) || (loc(GREEN_GOO) == FOOD_KIT) || (loc(BROWN_GOO) == FOOD_KIT))) {
      remove(RED_GOO);
      remove(GREEN_GOO);
      remove(BROWN_GOO);
      tell("Colored goo flies all over everything. Yechh!\n");
      return true;
    } else if (first(g.PRSO)) {
      loop1: for (;;) {
        if (x = first(g.PRSO)) {
          if (x == HIGH_PROTEIN || x == CHEMICAL_FLUID) {
            remove(x);
          } else {
            move(x, g.HERE);
          }
        } else {
          break loop1;
        }
      }
      tell("The contents of the ", D(g.PRSO), " spill onto the floor.\n");
      return true;
    } else {
      tell("You have shaken the ", D(g.PRSO), ".\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, CONTBIT)) {
    tell("The ", D(g.PRSO), " sounds empty.\n");
    return true;
  } else {
    tell("Shaken.\n");
    return true;
  }
}

