async function ACCESSIBLE$(obj) {
  let l = loc(obj);
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (obj == PSEUDO_OBJECT) {
    if (g.LAST_PSEUDO_LOC == g.HERE) {
      return true;
    } else {
      return false;
    }
  } else if (!l) {
    return false;
  } else if (l == GLOBAL_OBJECTS) {
    return true;
  } else if ((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(obj, g.HERE))) {
    return true;
  } else if (!(eq(await META_LOC(obj), g.HERE))) {
    return false;
  } else if (l == g.WINNER || l == g.HERE) {
    return true;
  } else if (hasFlag(l, OPENBIT) && (await ACCESSIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

async function VISIBLE$(obj) {
  let l = loc(obj);
  if (await ACCESSIBLE$(obj)) {
    return true;
  } else if ((await SEE_INSIDE$(l)) && (await VISIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

