async function COMBINATION_DIAL_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The dial can be turned to any number between 0 and 1000.\n");
    return true;
  } else if (isVerb(V.SET) && (g.PRSI == INTNUM)) {
    if (hasFlag(COMBINATION_DIAL, MUNGEDBIT)) {
      tell("The dial has somehow become fused and won't move.\n");
      return true;
    } else if (g.P_NUMBER == g.DIAL_NUMBER) {
      tell("That's what the dial is set to now!\n");
      return true;
    } else if (g.P_NUMBER == g.NUMBER_NEEDED) {
      g.DIAL_NUMBER = 0;
      setFlag(CONFERENCE_DOOR, OPENBIT);
      tell("The door swings open, and the dial resets to 0.\n");
      return true;
    } else if (g.P_NUMBER > 1000) {
      tell("The dial cannot be turned to a number that high.\n");
      return true;
    } else {
      g.DIAL_NUMBER = g.P_NUMBER;
      tell("The dial is now set to ", N(g.P_NUMBER), ".\n");
      return true;
    }
  } else {
    return false;
  }
}

async function CONFERENCE_DOOR_F() {
  if (isVerb(V.OPEN)) {
    if (hasFlag(CONFERENCE_DOOR, OPENBIT)) {
      return await ALREADY_OPEN();
    } else {
      if (g.HERE == REC_AREA) {
        tell("The door is locked. You probably have to turn the dial to some number to open it.\n");
        return true;
      } else {
        tell("The door seems to be locked from the other side.\n");
        return true;
      }
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(CONFERENCE_DOOR, OPENBIT)) {
      clearFlag(CONFERENCE_DOOR, OPENBIT);
      tell("The door closes and you hear a click as it locks.\n");
      return true;
    } else {
      return await IS_CLOSED();
    }
  } else {
    return false;
  }
}

async function MESS_CORRIDOR_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is a wide, east-west hallway with a large portal to the south. A small door to the north is ");
    await DDESC(STORAGE_WEST_DOOR);
    if (!g.PADLOCK_REMOVED) {
      tell(" and hooked with a simple steel padlock");
      if (hasFlag(PADLOCK, OPENBIT)) {
        tell(" which hangs unlocked");
      } else {
        tell(" which is also closed");
      }
    }
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

async function STORAGE_WEST_DOOR_F() {
  if (isVerb(V.OPEN)) {
    if (hasFlag(STORAGE_WEST_DOOR, OPENBIT)) {
      return await ALREADY_OPEN();
    } else if (g.PADLOCK_REMOVED) {
      setFlag(STORAGE_WEST_DOOR, OPENBIT);
      tell("Opened.\n");
      return true;
    } else {
      tell("The door cannot be opened until the padlock is removed.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(STORAGE_WEST_DOOR, OPENBIT)) {
      clearFlag(STORAGE_WEST_DOOR, OPENBIT);
      tell("The door is now closed.\n");
      return true;
    } else {
      return await IS_CLOSED();
    }
  } else if (isVerb(V.UNLOCK)) {
    tell("The door itself isn't locked.");
    if (!(hasFlag(PADLOCK, OPENBIT))) {
      tell(" It is the padlock on the door which is locked.");
    }
    tell("\n");
    return true;
  } else {
    return false;
  }
}

async function PADLOCK_F() {
  if (g.HERE == BRIG) {
    tell("You can't see or reach the lock from inside the cell.\n");
    return true;
  } else if (isVerb(V.OPEN_WITH) && (PADLOCK == g.PRSO)) {
    await PERFORM(V.UNLOCK, PADLOCK, g.PRSI);
    return true;
  } else if (isVerb(V.UNLOCK, V.OPEN)) {
    if (!(hasFlag(PADLOCK, OPENBIT))) {
      if (!g.PRSI) {
        tell("You can't open it with your hands.\n");
        return true;
      } else if (g.PRSI == KEY) {
        if (hasFlag(PADLOCK, MUNGEDBIT)) {
          tell("Tsk, tsk ... the padlock seems to be fused shut.\n");
          return true;
        } else {
          setFlag(PADLOCK, OPENBIT);
          tell("The padlock springs open.\n");
          return true;
        }
      } else {
        tell("That doesn't work.\n");
        return true;
      }
    } else {
      tell("The padlock is already unlocked.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE, V.LOCK)) {
    if (hasFlag(PADLOCK, OPENBIT)) {
      clearFlag(PADLOCK, OPENBIT);
      tell("The padlock closes with a sharp click.\n");
      return true;
    } else {
      tell("The padlock is already locked.\n");
      return true;
    }
  } else if (isVerb(V.TAKE) && !g.PADLOCK_REMOVED) {
    if (hasFlag(PADLOCK, OPENBIT)) {
      g.PADLOCK_REMOVED = true;
      clearFlag(PADLOCK, TRYTAKEBIT);
      clearFlag(PADLOCK, NDESCBIT);
      return false;
    } else if (!(hasFlag(PADLOCK, OPENBIT))) {
      tell("The padlock is locked to the door.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.MUNG)) {
    tell("And, as we go into the next round, it's Padlock 1, Adventurer 0...\n");
    return true;
  } else {
    return false;
  }
}

async function CAN_F() {
  if (isVerb(V.EXAMINE)) {
    tell("This is a rather normal tin can. It is large and is labelled \"Spam and Egz.\"\n");
    return true;
  } else if (isVerb(V.OPEN)) {
    tell("You certainly can't open it with your hands, and you don't seem to have found a can opener yet.\n");
    return true;
  } else {
    return false;
  }
}

async function LADDER_F() {
  if (isVerb(V.TAKE)) {
    if (g.LADDER_EXTENDED) {
      tell("You can't possibly carry the ladder while it's extended.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("It is a heavy-duty ladder built of sturdy aluminum tubing. It is currently ");
    if (g.LADDER_EXTENDED) {
      tell("extended to its full length of about 8 meters, but could be collapsed to a shorter length for easier carrying.\n");
      return true;
    } else {
      tell("collapsed and is around two-and-a-half meters long, but if extended would obviously be much longer.\n");
      return true;
    }
  } else if (isVerb(V.OPEN)) {
    if (g.LADDER_EXTENDED) {
      tell("The ladder is already extended.\n");
      return true;
    } else if ((g.HERE == STORAGE_EAST || g.HERE == STORAGE_WEST || g.HERE == BOOTH_2) || (g.HERE == UPPER_ELEVATOR || g.HERE == LOWER_ELEVATOR)) {
      tell("You can't extend the ladder in this tiny space!\n");
      return true;
    } else if (loc(LADDER) == ADVENTURER) {
      tell("You couldn't possibly extend the ladder while you're holding it.\n");
      return true;
    } else {
      setFlag(LADDER, TRYTAKEBIT);
      g.LADDER_EXTENDED = true;
      g.C_ELAPSED = 36;
      tell("The ladder extends to a length of around eight meters.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    if (g.LADDER_EXTENDED) {
      g.C_ELAPSED = 21;
      if (g.LADDER_FLAG) {
        g.LADDER_FLAG = false;
        remove(LADDER);
        tell("As the ladder shortens it plunges into the rift.\n");
        return true;
      } else {
        g.LADDER_EXTENDED = false;
        clearFlag(LADDER, TRYTAKEBIT);
        tell("The ladder collapses to a length of around two-and-a-half meters.\n");
        return true;
      }
    } else {
      tell("The ladder is already in its collapsed state.\n");
      return true;
    }
  } else if (isVerb(V.SPAN, V.ATTRACT) && (g.PRSI == RIFT)) {
    if (g.LADDER_FLAG) {
      tell("The ladder already spans the rift.\n");
      return true;
    } else {
      if (g.LADDER_EXTENDED) {
        g.LADDER_FLAG = true;
        setFlag(LADDER, NDESCBIT);
        tell("The ladder swings out across the rift and comes to rest on the far edge, spanning the precipice.\n");
        return true;
      } else {
        remove(LADDER);
        tell("The ladder, far too short to reach the other edge of the rift, plunges into the rift and is lost forever.\n");
        return true;
      }
    }
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_FOO)) {
    if (g.LADDER_FLAG) {
      tell("You can't climb a horizontal ladder!\n");
      return true;
    } else if (loc(LADDER) == ADVENTURER) {
      tell("That would be a neat trick, considering that you're holding it.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

