async function HIGH_PROTEIN_F() {
  let x = false;
  if (isVerb(V.EAT)) {
    if (!(loc(CANTEEN) == ADVENTURER)) {
      g.PRSO = CANTEEN;
      return await NOT_HOLDING();
    } else {
      if (g.HUNGER_LEVEL == 0) {
        tell(S(g.NOT_HUNGRY), "\n");
        return true;
      } else {
        remove(HIGH_PROTEIN);
        g.C_ELAPSED = 15;
        g.HUNGER_LEVEL = 0;
        enable(await QUEUE(I_HUNGER_WARNINGS.id, 3600));
        tell("Mmmm....that was good. It certainly quenched your thirst and satisfied your hunger.\n");
        return true;
      }
    }
  } else if (isVerb(V.POUR) && (g.PRSO == HIGH_PROTEIN)) {
    if (!(loc(CANTEEN) == ADVENTURER)) {
      tell("Maybe if you were holding the canteen...\n");
      return true;
    } else if (!g.PRSI) {
      g.PRSI = GROUND;
    }
    if (g.PRSI == FLASK) {
      return await WORTHLESS_ACTION();
    } else if (g.PRSI == FUNNEL_HOLE) {
      if (loc(CHEMICAL_FLUID) == FLASK) {
        x = true;
      }
      g.CHEMICAL_REQUIRED = 10;
      remove(HIGH_PROTEIN);
      await PERFORM(V.POUR, CHEMICAL_FLUID, FUNNEL_HOLE);
      if (x) {
        move(CHEMICAL_FLUID, FLASK);
      }
      return true;
    } else {
      remove(HIGH_PROTEIN);
      tell("The protein-rich fluid pours over the ", D(g.PRSI), " and then dries up.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function WORTHLESS_ACTION() {
  tell("A worthless action -- and much too difficult for a poorly-written program like this one to handle.\n");
  return true;
}

