async function ELEVATOR_BUTTON_F() {
  if (isVerb(V.PUSH_UP)) {
    if ((g.HERE == LOWER_ELEVATOR) && (g.LOWER_ELEVATOR_UP == false) && (g.LOWER_ELEVATOR_ON == true) && (g.ELEVATOR_IN_TRANSIT == false)) {
      tell(S(g.ELEVATOR_STARTS), "\n");
      clearFlag(LOWER_ELEVATOR_DOOR, OPENBIT);
      g.ELEVATOR_IN_TRANSIT = true;
      return enable(await QUEUE(I_LOWER_ELEVATOR_TRIP.id, 100));
    } else if ((g.HERE == UPPER_ELEVATOR) && (g.UPPER_ELEVATOR_UP == false) && (g.UPPER_ELEVATOR_ON == true) && (g.ELEVATOR_IN_TRANSIT == false)) {
      tell(S(g.ELEVATOR_STARTS), "\n");
      clearFlag(UPPER_ELEVATOR_DOOR, OPENBIT);
      g.ELEVATOR_IN_TRANSIT = true;
      return enable(await QUEUE(I_UPPER_ELEVATOR_TRIP.id, 50));
    } else {
      tell("Nothing happens.\n");
      return true;
    }
  } else if (isVerb(V.PUSH_DOWN)) {
    if ((g.HERE == LOWER_ELEVATOR) && (g.LOWER_ELEVATOR_UP == true) && (g.LOWER_ELEVATOR_ON == true) && (g.ELEVATOR_IN_TRANSIT == false)) {
      tell(S(g.ELEVATOR_STARTS), "\n");
      clearFlag(LOWER_ELEVATOR_DOOR, OPENBIT);
      g.ELEVATOR_IN_TRANSIT = true;
      return enable(await QUEUE(I_LOWER_ELEVATOR_TRIP.id, 100));
    } else if ((g.HERE == UPPER_ELEVATOR) && (g.UPPER_ELEVATOR_UP == true) && (g.UPPER_ELEVATOR_ON == true) && (g.ELEVATOR_IN_TRANSIT == false)) {
      tell(S(g.ELEVATOR_STARTS), "\n");
      clearFlag(UPPER_ELEVATOR_DOOR, OPENBIT);
      g.ELEVATOR_IN_TRANSIT = true;
      return enable(await QUEUE(I_UPPER_ELEVATOR_TRIP.id, 50));
    } else {
      tell("Nothing happens.\n");
      return true;
    }
  } else if (isVerb(V.PUSH)) {
    tell("You must specify whether you want to push the Up button or the Down button.\n");
    return true;
  } else {
    return false;
  }
}

