async function TERMINAL_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The computer terminal consists of a video display screen, a keyboard with ten keys numbered from zero through nine, and an on-off switch. ");
    if (hasFlag(TERMINAL, ONBIT)) {
      tell("The screen displays some writing:\n", S(g.SCREEN_TEXT), "\n");
      if (g.MENU_LEVEL > 9) {
        tell(S(g.MORE_INFO), "\n");
      }
      return true;
    } else {
      tell("The screen is dark.\n");
      return true;
    }
  } else if (isVerb(V.READ)) {
    if (hasFlag(TERMINAL, ONBIT)) {
      tell(S(g.SCREEN_TEXT), "\n");
      if (g.MENU_LEVEL > 9) {
        tell(S(g.MORE_INFO), "\n");
      }
      return true;
    } else {
      tell("The screen is blank.\n");
      return true;
    }
  } else if (isVerb(V.LAMP_ON)) {
    if (hasFlag(TERMINAL, ONBIT)) {
      tell("It's already on.\n");
      return true;
    } else {
      setFlag(TERMINAL, ONBIT);
      setFlag(TERMINAL, TOUCHBIT);
      g.SCREEN_TEXT = g.MAIN_MENU;
      tell("The screen gives off a green flash, and then some writing appears on the screen:\n");
      tell(S(g.SCREEN_TEXT), "\n");
      return true;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (hasFlag(TERMINAL, ONBIT)) {
      clearFlag(TERMINAL, ONBIT);
      g.MENU_LEVEL = 0;
      tell("The screen goes dark.\n");
      return true;
    } else {
      tell("It isn't on!\n");
      return true;
    }
  } else {
    return false;
  }
}

