async function SPOOL_READER_F() {
  if (isVerb(V.LAMP_ON)) {
    if (hasFlag(SPOOL_READER, ONBIT)) {
      tell("The spool reader is already on.\n");
      return true;
    } else {
      setFlag(SPOOL_READER, ONBIT);
      setFlag(SPOOL_READER, TOUCHBIT);
      if (first(SPOOL_READER)) {
        tell(S(g.SPOOL_TEXT), "\n");
        return true;
      } else {
        tell("The machine hums quietly, and the screen lights up with the phrase \"Pleez insurt spuul.\"\n");
        return true;
      }
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (hasFlag(SPOOL_READER, ONBIT)) {
      clearFlag(SPOOL_READER, ONBIT);
      tell("The spool reader is now off.\n");
      return true;
    } else {
      tell("It's not on!\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("The machine has a small screen, and below that, a small circular opening. The screen is currently ");
    if (hasFlag(SPOOL_READER, ONBIT) && first(SPOOL_READER)) {
      tell("displaying some information:\n");
      tell(S(g.SPOOL_TEXT), "\n");
      return true;
    } else {
      tell("blank.\n");
      return true;
    }
  } else if (isVerb(V.READ)) {
    if (hasFlag(SPOOL_READER, ONBIT) && first(SPOOL_READER)) {
      tell(S(g.SPOOL_TEXT), "\n");
      return true;
    } else {
      tell("The screen is blank.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == SPOOL_READER)) {
    if (first(SPOOL_READER)) {
      tell("There's already a spool in the reader.\n");
      return true;
    } else if (g.PRSO == GREEN_SPOOL) {
      g.SPOOL_TEXT = g.GREEN_TEXT;
      move(GREEN_SPOOL, SPOOL_READER);
      setFlag(GREEN_SPOOL, TRYTAKEBIT);
      tell(S(g.SPOOL_FITS));
      if (hasFlag(SPOOL_READER, ONBIT)) {
        tell(S(g.SOME_INFO));
      }
      tell("\n");
      return true;
    } else if (g.PRSO == RED_SPOOL) {
      g.SPOOL_TEXT = g.RED_TEXT;
      move(RED_SPOOL, SPOOL_READER);
      setFlag(RED_SPOOL, TRYTAKEBIT);
      tell(S(g.SPOOL_FITS));
      if (hasFlag(SPOOL_READER, ONBIT)) {
        tell(S(g.SOME_INFO));
      }
      tell("\n");
      return true;
    } else {
      tell("It doesn't fit in the circular opening.\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    await NO_CLOSE();
    return true;
  } else {
    return false;
  }
}

