async function BIO_LOCK_EAST_F(rarg) {
  if ((rarg == M_END) && (loc(FLOYD) == g.HERE) && hasFlag(FLOYD, RLANDBIT) && !(FLOYD == g.WINNER)) {
    if (g.FLOYD_WAITING) {
      if (g.WAITING_COUNTER > 3) {
        g.FLOYD_WAITING = false;
        g.FLOYD_GAVE_UP = true;
        g.FLOYD_SPOKE = true;
        g.FLOYD_FOLLOW = false;
        move(FLOYD, BIO_LOCK_WEST);
        enable(await QUEUE(I_FLOYD.id, 1));
        tell("\"Okay,\" says Floyd with uncharacteristic annoyance. \"Forget about the stupid card.\" He goes to the other end of the bio-lock and sulks.\n");
        return true;
      } else if (!g.FLOYD_FORAYED) {
        g.FLOYD_SPOKE = true;
        g.WAITING_COUNTER = g.WAITING_COUNTER + 1;
        tell("Floyd looks at you with a dash of impatience and a healthy helping of nervousness. \"Well?\" he asks. \"Are you going to open the door?\"\n");
        return true;
      } else {
        return false;
      }
    } else if (!g.FLOYD_GAVE_UP && !g.FLOYD_PEERED) {
      g.FLOYD_SPOKE = true;
      g.FLOYD_PEERED = true;
      enable(await QUEUE(I_CLEAR_FLOYD_PEER.id, 40));
      clearFlag(MINI_CARD, INVISIBLE);
      tell("Floyd stands on his tiptoes and peers in the window. ");
      if (g.COMPUTER_FLAG) {
        g.FLOYD_WAITING = true;
        tell("\"Looks dangerous in there,\" says Floyd. \"I don't think you should go inside.\" He peers in again. \"We'll need card there to fix computer. Hmmm... I know! Floyd will get card. Robots are tough. Nothing can hurt robots. You open the door, then Floyd will rush in. Then you close door. When Floyd knocks, open door again. Okay? Go!\" Floyd's voice trembles slightly as he waits for you to open the door.");
      } else {
        tell("\"Ooo, look,\" he says. \"There's a miniaturization booth access card!\"");
      }
      tell("\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

