async function BIO_DOOR_EAST_F() {
  if (isVerb(V.OPEN)) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      return await ALREADY_OPEN();
    } else if (hasFlag(BIO_DOOR_WEST, OPENBIT)) {
      tell(S(g.BOTH_DOORS), "\n");
      return true;
    } else if (g.FLOYD_WAITING && hasFlag(FLOYD, RLANDBIT) && (g.FORAY_COUNTER == 0)) {
      enable(await QUEUE(I_FLOYD_FORAY.id, -1));
      g.FLOYD_FORAYED = true;
      setFlag(BIO_DOOR_EAST, OPENBIT);
      remove(FLOYD);
      disable(await INT(I_FLOYD.id));
      tell("The door opens and Floyd, pausing only for the briefest moment, plunges into the Bio Lab. Immediately, he is set upon by hideous, mutated monsters! More are heading straight toward the open door! Floyd shrieks and yells to you to close the door.\n");
      return true;
    } else if (!g.FLOYD_FORAYED && eq(get(await INT(I_CHASE_SCENE.id), C_ENABLED$), 0)) {
      return (await JIGS_UP("Opening the door reveals a Bio-Lab full of horrible mutations. You stare at them, frozen with horror. Growling with hunger and delight, the mutations march into the bio-lock and devour you."));
    } else {
      setFlag(BIO_DOOR_EAST, OPENBIT);
      enable(await QUEUE(I_BIO_EAST_CLOSES.id, 30));
      tell(S(g.DOOR_OPENS), "\n");
      return true;
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      if (g.FORAY_COUNTER == 4) {
        g.C_ELAPSED = 95;
      }
      clearFlag(BIO_DOOR_EAST, OPENBIT);
      tell("The door closes");
      if (eq(get(await INT(I_CHASE_SCENE.id), C_ENABLED$), 1)) {
        tell(", but not soon enough!\n");
        return true;
      } else {
        tell(".\n");
        return true;
      }
    } else {
      return await IS_CLOSED();
    }
  } else {
    return false;
  }
}

