async function I_FLOYD_FORAY() {
  g.FORAY_COUNTER = g.FORAY_COUNTER + 1;
  if (g.FORAY_COUNTER == 2) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      crlf();
      return await MONSTER_DEATH();
    } else {
      tell("\nFrom within the lab you hear ferocious growlings, the sounds of a skirmish, and then a high-pitched metallic scream!\n");
      return true;
    }
  } else if (g.FORAY_COUNTER == 3) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      crlf();
      return await MONSTER_DEATH();
    } else {
      tell("\nYou hear, slightly muffled by the door, three fast knocks, followed by the distinctive sound of tearing metal.\n");
      return true;
    }
  } else if (g.FORAY_COUNTER == 4) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      move(FLOYD, g.HERE);
      tell("\nFloyd stumbles out of the Bio Lab, clutching the mini-booth card. The mutations rush toward the open doorway!\n");
      return true;
    } else {
      tell("\nThe three knocks come again, followed by a wild scream. Then, all is silence from within the Bio Lab, except for an occasional metallic crunch.\n");
      clearFlag(FLOYD, RLANDBIT);
      return disable(await INT(I_FLOYD_FORAY.id));
    }
  } else if (g.FORAY_COUNTER == 5) {
    if (hasFlag(BIO_DOOR_EAST, OPENBIT)) {
      crlf();
      return await MONSTER_DEATH();
    } else {
      remove(FLOYD);
      clearFlag(FLOYD, RLANDBIT);
      disable(await INT(I_FLOYD.id));
      setFlag(FLOYD, INVISIBLE);
      move(DEAD_FLOYD, g.HERE);
      move(MINI_CARD, BIO_LOCK_EAST);
      setFlag(MINI_CARD, TOUCHBIT);
      g.SCORE = g.SCORE + 2;
      tell("\nAnd not a moment too soon! You hear a pounding from the door as the monsters within vent their frustration at losing their prey.\n\nFloyd staggers to the ground, dropping the mini card. He is badly torn apart, with loose wires and broken circuits everywhere. Oil flows from his lubrication system. He obviously has only moments to live.\n\nYou drop to your knees and cradle Floyd's head in your lap. Floyd looks up at his friend with half-open eyes. \"Floyd did it ... got card. Floyd a good friend, huh?\" Quietly, you sing Floyd's favorite song, the Ballad of the Starcrossed Miner:\n\nO, they ruled the solar system\nNear ten thousand years before\nIn their single starcrossed scout ships\nMining ast'roids, spinning lore.\n\nThen one true courageous miner\nSpied a spaceship from the stars\nBoarded he that alien liner\nOut beyond the orb of Mars.\n\nYes, that ship was filled with danger\nMighty monsters barred his way\nYet he solved the alien myst'ries\nMining quite a lode that day.\n\nO, they ruled the solar system\nNear ten thousand years before\n'Til one brave advent'rous spirit\nBrought that mighty ship to shore.\n\nAs you finish the last verse, Floyd smiles with contentment, and then his eyes close as his head rolls to one side. You sit in silence for a moment, in memory of a brave friend who gave his life so that you might live.\n");
      clearFlag(FLOYD, RLANDBIT);
      clearFlag(MINI_CARD, NDESCBIT);
      return disable(await INT(I_FLOYD_FORAY.id));
    }
  } else {
    return false;
  }
}

