async function LASER_F(rarg = false) {
  if (isVerb(V.SET) && (g.PRSI == INTNUM)) {
    await PERFORM(V.SET, LASER_DIAL, g.PRSI);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The laser, though portable, is still fairly heavy. It has a long, slender barrel and a dial with six settings, labelled \"1\" through \"6.\" This dial is currently on setting ", N(g.LASER_SETTING), ". There is a depression on the top of the laser which ");
    if (loc(OLD_BATTERY) == LASER) {
      tell("contains an ", D(OLD_BATTERY));
    } else if (loc(NEW_BATTERY) == LASER) {
      tell("contains a ", D(NEW_BATTERY));
    } else {
      tell("is empty");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    tell("There doesn't seem to be any way to do that to this laser.\n");
    return true;
  } else if (isVerb(V.PUT)) {
    if (g.PRSO == OLD_BATTERY) {
      if (loc(NEW_BATTERY) == LASER) {
        return await ALREADY_BATTERY();
      } else {
        move(OLD_BATTERY, LASER);
        return await BATTERY_NOW();
      }
    } else if (g.PRSO == NEW_BATTERY) {
      if (loc(OLD_BATTERY) == LASER) {
        return await ALREADY_BATTERY();
      } else {
        move(NEW_BATTERY, LASER);
        return await BATTERY_NOW();
      }
    } else if (!(LASER == g.PRSO)) {
      tell("The ", D(g.PRSO), " doesn't fit the depression.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ZAP)) {
    if (!(loc(LASER) == ADVENTURER)) {
      await NOT_HOLDING();
      return true;
    }
    if (!g.LASER_SCORE_FLAG) {
      g.LASER_SCORE_FLAG = true;
      g.SCORE = g.SCORE + 2;
    }
    if ((g.PRSI == LASER) || (g.PRSI == LASER_DIAL) || ((g.PRSI == OLD_BATTERY) && (loc(OLD_BATTERY) == LASER)) || ((g.PRSI == NEW_BATTERY) && (loc(NEW_BATTERY) == LASER))) {
      tell("Sorry, the laser doesn't have a rubber barrel.\n");
      return true;
    } else if (await ZAP_COUNT()) {
      tell("Click.\n");
      return true;
    } else if (hasFlag(LASER, MUNGEDBIT)) {
      tell("The laser sparks a few times, whines, and then stops.\n");
      return true;
    } else {
      enable(await QUEUE(I_WARMTH.id, -1));
      g.LASER_JUST_SHOT = true;
      if (g.PRSI == SPECK) {
        await SHOOT_SPECK();
        return true;
      } else if (g.PRSI == MICROBE) {
        await SHOOT_MICROBE();
        return true;
      } else if (g.PRSI == ME || g.PRSI == HANDS || g.PRSI == ADVENTURER) {
        tell("Ouch! You managed to burn yourself nicely.\n");
        return true;
      } else {
        tell("The laser emits a narrow ");
        await BEAM_COLOR();
        tell(" beam of light");
        if (g.PRSI) {
          if ((g.PRSI == TOWEL || g.PRSI == BROCHURE || g.PRSI == COMBINATION_PAPER) || (g.PRSI == PRINT_OUT || g.PRSI == LAB_UNIFORM || g.PRSI == PATROL_UNIFORM) || (g.PRSI == ID_CARD || g.PRSI == KITCHEN_CARD || g.PRSI == MINI_CARD) || (g.PRSI == TELEPORTATION_CARD || g.PRSI == SHUTTLE_CARD || g.PRSI == UPPER_ELEVATOR_CARD) || (g.PRSI == LOWER_ELEVATOR_CARD)) {
            remove(g.PRSI);
            if (g.PRSI == g.SPOUT_PLACED) {
              g.SPOUT_PLACED = GROUND;
            }
            tell(" which strikes the ", D(g.PRSI), ". The ", D(g.PRSI), " bursts into flame, blinding you momentarily, and is quickly consumed.\n");
            return true;
          } else if ((g.PRSI == FLOYD) && hasFlag(FLOYD, RLANDBIT)) {
            tell(" which strikes Floyd. \"Yow!\" yells Floyd. He jumps to the other end of the room and eyes you warily.\n");
            return true;
          } else if ((g.PRSI == PSEUDO_OBJECT) && (g.HERE == PROJCON_OFFICE)) {
            tell(" which strikes the ", D(g.PRSI), ". However, this doesn't seem to affect it.\n");
            return true;
          } else {
            tell(" which strikes the ", D(g.PRSI), ". The ", D(g.PRSI), " grows a bit warm, but nothing else happens.\n");
            return true;
          }
        } else {
          tell(".\n");
          return true;
        }
      }
    }
  } else if (isVerb(V.DROP)) {
    disable(await INT(I_WARMTH.id));
    if ((loc(MICROBE) == g.HERE) && (g.WARMTH_FLAG > 7)) {
      remove(LASER);
      tell("The microbe rushes to envelop the laser. You hear a faint burp as the monster begins to look around for other morsels...\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

