async function SHOOT_SPECK() {
  let $1;
  if (g.LASER_SETTING == 1) {
    if (prob(g.MARKSMANSHIP_COUNTER)) {
      if (g.SPECK_HIT) {
        g.COMPUTER_FIXED = true;
        setFlag(CRYO_ELEVATOR_DOOR, OPENBIT);
        clearFlag(PROJCON_OFFICE, TOUCHBIT);
        clearFlag(CRYO_ELEVATOR_DOOR, INVISIBLE);
        enable(await QUEUE(I_FRY.id, 200));
        g.SCORE = g.SCORE + 8;
        remove(SPECK);
        tell("The beam hits the speck again! This time, it vaporizes into a fine cloud of ash. The relay slowly begins to close, and a voice whispers in your ear \"Sector 384 will activate in 200 millichrons. Proceed to exit station.\"\n");
        return true;
      } else {
        g.SPECK_HIT = true;
        tell("The speck is hit by the beam! It sizzles a little, but isn't destroyed yet.\n");
        return true;
      }
    } else {
      g.MARKSMANSHIP_COUNTER = g.MARKSMANSHIP_COUNTER + 12;
      $1 = await PICK_ONE(g.BEAM_MISSES);
      tell(S($1));
      tell("\n");
      return true;
    }
  } else {
    remove(RELAY);
    tell("A thin ");
    await BEAM_COLOR();
    tell(" beam shoots from the laser and slices through the red plastic covering of the relay like a hot knife through butter. Air rushes into the relay, which collapses into a heap of plastic shards.\n");
    return true;
  }
}

async function I_FRY() {
  if (g.HERE == MIDDLE_OF_STRIP || g.HERE == STRIP_NEAR_STATION || g.HERE == STRIP_NEAR_RELAY) {
    crlf();
    return (await JIGS_UP("\nWith a furious storm of electrical mayhem, Sector 384 comes to life. A few micro-volts course through the silicon strip on which you stand. Unfortunately, at your current size, this is enough to barbecue you."));
  } else {
    return false;
  }
}

async function MICROBE_F() {
  if (isVerb(V.HELLO, V.TALK) || (MICROBE == g.WINNER)) {
    tell("You don't seem to have bridged the vast communication gulf between yourself and the microbe.\n");
    g.P_CONT = false;
    g.QUOTE_FLAG = false;
    return M_FATAL;
  } else if (isVerb(V.THROW, V.GIVE) && (g.PRSI == MICROBE)) {
    if ((g.PRSO == LASER) && (g.WARMTH_FLAG > 7)) {
      remove(LASER);
      disable(await INT(I_WARMTH.id));
      if (g.WARMTH_FLAG > 10) {
        disable(await INT(I_MICROBE.id));
        tell("The microbe gobbles up the laser and turns toward you. A moment later, it begins writhing in pain. Apparently, eating the hot laser was a bit too much for it. With a bellow of agony, it rolls off the edge of the strip. (Whew!)\n");
        remove(LASER);
        remove(MICROBE);
        g.NO_MICROBE = true;
        return g.MICROBE_DISPATCHED = true;
      } else {
        tell("The microbe greedily devours the laser, and turns toward you.\n");
        return true;
      }
    } else {
      tell("The microbe ignores the ", D(g.PRSO), ", but does attempt to digest your arm.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function I_MICROBE() {
  let $1, $2;
  if (g.MICROBE_HIT == true) {
    tell("\n");
    $1 = await PICK_ONE(g.WINNER_ATTACKED);
    tell(S($1));
    if ((g.WARMTH_FLAG > 13) && (loc(LASER) == ADVENTURER)) {
      (await JIGS_UP(" The microbe, whipped into a rabid frenzy by the waves of heat from the pulsing laser, literally lunges at it. You jump back and, losing your balance, fall over the edge of the strip. The microbe, writhing madly, hurls itself after its prey. You and the microbe both plunge into the void below."));
    } else if ((g.WARMTH_FLAG > 7) && (loc(LASER) == ADVENTURER)) {
      tell(" Another pseudopod, perhaps attracted by the warmth of the laser, tries to envelop the weapon. You snatch it away from the monster's grasp.");
    }
    crlf();
  } else {
    if (g.MICROBE_COUNTER == 2) {
      (await JIGS_UP("\nThe microbe wraps several pseudopods around you and shoves you into its mucus-covered gullet. Digestive juices begin their work. The experience is not pleasant."));
    } else {
      g.MICROBE_COUNTER = g.MICROBE_COUNTER + 1;
      tell("\n");
      $2 = await PICK_ONE(g.MONSTER_CLOSES);
      tell(S($2));
      tell("\n");
    }
  }
  return g.MICROBE_HIT = false;
}

async function SHOOT_MICROBE() {
  let $1;
  tell("The laser beam strikes the microbe");
  if (g.LASER_SETTING == 1) {
    tell(", but passes harmlessly through its red skin.\n");
    return true;
  } else {
    g.MICROBE_HIT = true;
    tell(". ");
    $1 = await PICK_ONE(g.MICROBE_STRIKES);
    tell(S($1));
    tell("\n");
    return true;
  }
}

async function STRIP_F() {
  if (isVerb(V.THROW_OFF)) {
    if ((g.PRSO == LASER) && (g.WARMTH_FLAG > 7)) {
      disable(await INT(I_WARMTH.id));
      disable(await INT(I_MICROBE.id));
      tell("As the laser flies over the edge of the strip, the hungry microbe lunges after it. Both the laser and the microbe plummet into the void. (Whew!)\n");
      remove(LASER);
      remove(MICROBE);
      g.NO_MICROBE = true;
      return g.MICROBE_DISPATCHED = true;
    } else {
      if (g.PRSO == LASER) {
        disable(await INT(I_WARMTH.id));
      }
      remove(g.PRSO);
      tell("The ", D(g.PRSO), " flies over the edge of the strip and disappears into the void.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GRUE_F() {
  if (isVerb(V.EXAMINE) && !(loc(GRUE) == g.HERE)) {
    tell("Grues are vicious, carnivorous beasts first introduced to Earth by a visiting alien spaceship during the late 22nd century. Grues spread throughout the galaxy alongside man. Although now extinct on all civilized planets, they still exist in some backwater corners of the galaxy. Their favorite diet is Ensigns Seventh Class, but their insatiable appetite is tempered by their fear of light.\n");
    return true;
  } else {
    return false;
  }
}

